import { cc } from "sinwan/component";

import { toggleVariants } from "@/components/ui/toggle";
import { cn } from "@/lib/utils";
import { ToggleGroupItem as ToggleGroupItemPrimitive, ToggleGroupRoot } from "sinwan-ui-core/controls";

import {
  useToggleGroupItem,
  useToggleGroupRoot,
  type ToggleGroupItemProps,
  type ToggleGroupProps,
} from "./useToggleGroup";

const ToggleGroup = cc<ToggleGroupProps>((props) => {
  const root = useToggleGroupRoot(props);
  return (
    <ToggleGroupRoot
      data-variant={root.variant.value ?? undefined}
      data-size={root.size.value ?? undefined}
      data-spacing={root.spacing.value}
      data-orientation={root.orientation.value}
      style={{ "--gap": String(root.spacing.value) }}
      class={cn(
        "group/toggle-group flex w-fit flex-row items-center gap-[--spacing(var(--gap))] rounded-lg data-[size=sm]:rounded-[min(var(--radius-md),10px)] data-vertical:flex-col data-vertical:items-stretch",
        root.orientation.value === "vertical" && "flex-col items-stretch",
        root.size.value === "sm" && "rounded-[min(var(--radius-md),10px)]",
        root.class,
      )}
      {...root.rest}
    >
      {root.children}
    </ToggleGroupRoot>
  );
});

const ToggleGroupItem = cc<ToggleGroupItemProps>((props) => {
  const item = useToggleGroupItem(props);
  return (
    <ToggleGroupItemPrimitive
      data-variant={item.variant ?? undefined}
      data-size={item.size ?? undefined}
      data-spacing={item.spacing}
      class={cn(
        "shrink-0 focus:z-10 focus-visible:z-10",
        item.spacing === 0 &&
          "rounded-none px-2 has-data-[icon=inline-end]:pr-1.5 has-data-[icon=inline-start]:pl-1.5 first:rounded-l-lg last:rounded-r-lg data-[variant=outline]:border-l-0 data-[variant=outline]:first:border-l",
        item.orientation === "vertical" &&
          item.spacing === 0 &&
          "first:rounded-t-lg first:rounded-l-none last:rounded-b-lg last:rounded-r-none data-[variant=outline]:border-t-0 data-[variant=outline]:border-l data-[variant=outline]:first:border-t",
        toggleVariants({
          variant: item.variant,
          size: item.size,
        }),
        item.class,
      )}
      {...item.rest}
    >
      {item.children}
    </ToggleGroupItemPrimitive>
  );
});

export { ToggleGroup, ToggleGroupItem };

import {
  getRawProps,
  inject,
  provide,
  type InjectionKey,
  type SinwanNode,
} from "sinwan/component";
import { computed, type Computed } from "sinwan/reactivity";
import type { VariantProps } from "class-variance-authority";

import type { toggleVariants } from "@/components/ui/toggle";

type ToggleVariant = VariantProps<typeof toggleVariants>["variant"];
type ToggleSize = VariantProps<typeof toggleVariants>["size"];

export type ToggleGroupOrientation = "horizontal" | "vertical";

export type ToggleGroupContext = VariantProps<typeof toggleVariants> & {
  spacing?: number;
  orientation?: ToggleGroupOrientation;
};

export type ToggleGroupProps = ToggleGroupContext & {
  children?: SinwanNode;
  type?: "single" | "multiple";
  value?: string | string[];
  defaultValue?: string | string[];
  onValueChange?: (v: string | string[]) => void;
  class?: string;
};

export type ToggleGroupItemProps = {
  children?: SinwanNode;
  class?: string;
  value: string;
  disabled?: boolean;
  variant?: ToggleVariant;
  size?: ToggleSize;
};

export type ToggleGroupRootRest = Omit<
  ToggleGroupProps,
  "class" | "variant" | "size" | "spacing" | "orientation" | "children"
>;

export type ToggleGroupRootReturn = {
  class: string | undefined;
  children: SinwanNode | undefined;
  rest: ToggleGroupRootRest;
  variant: Computed<ToggleVariant>;
  size: Computed<ToggleSize>;
  spacing: Computed<number>;
  orientation: Computed<ToggleGroupOrientation>;
};

export type ToggleGroupItemRest = Omit<
  ToggleGroupItemProps,
  "class" | "children" | "variant" | "size"
>;

export type ToggleGroupItemReturn = {
  class: string | undefined;
  children: SinwanNode | undefined;
  rest: ToggleGroupItemRest;
  variant: ToggleVariant;
  size: ToggleSize;
  spacing: number;
  orientation: ToggleGroupOrientation | undefined;
};

const ToggleGroupStyleKey: InjectionKey<ToggleGroupContext> = Symbol(
  "sinwan-ui.toggle-group-style",
);

/**
 * Resolves group style defaults and provides them to `ToggleGroupItem`s.
 */
export function useToggleGroupRoot(
  props: ToggleGroupProps,
): ToggleGroupRootReturn {
  const {
    class: className,
    variant: _variant,
    size: _size,
    spacing: _spacing,
    orientation: _orientation,
    children,
    ...rest
  } = getRawProps(props);
  const variant = computed(() => props.variant ?? "default");
  const size = computed(() => props.size ?? "default");
  const spacing = computed(() => props.spacing ?? 2);
  const orientation = computed(() => props.orientation ?? "horizontal");
  provide(ToggleGroupStyleKey, {
    variant: props.variant ?? "default",
    size: props.size ?? "default",
    spacing: props.spacing ?? 2,
    orientation: props.orientation ?? "horizontal",
  });
  return { class: className, children, rest, variant, size, spacing, orientation };
}

/**
 * Reads the nearest group style, or the default style outside a group.
 */
export function useToggleGroup(): ToggleGroupContext {
  return (
    inject(ToggleGroupStyleKey) ?? {
      variant: "default",
      size: "default",
      spacing: 2,
      orientation: "horizontal",
    }
  );
}

/**
 * Resolves an item's variant, size, and spacing from the group context.
 */
export function useToggleGroupItem(
  props: ToggleGroupItemProps,
): ToggleGroupItemReturn {
  const {
    class: className,
    children,
    variant = "default",
    size = "default",
    ...rest
  } = getRawProps(props);
  const context = useToggleGroup();
  return {
    class: className,
    children,
    rest,
    variant: context.variant || variant,
    size: context.size || size,
    spacing: context.spacing ?? 2,
    orientation: context.orientation,
  };
}
